static List<String> rawHttpGet(String host, String path) {
    List<String> wynik = new ArrayList<>();
    try (Socket socket = new Socket(host, 80)) {
        socket.setSoTimeout(5000);
        String request = "GET "+path+" HTTP/1.1\r\nHost: "+host+"\r\nConnection: close\r\n\r\n";
        socket.getOutputStream().write(request.getBytes(StandardCharsets.UTF_8));
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        String linia;
        while ((linia = reader.readLine()) != null) wynik.add(linia);
    } catch (IOException e) {}
    return wynik;
}
System.out.println(rawHttpGet("example.com", "/").size());

static int extractStatusCode(List<String> odpowiedz) {
    if (odpowiedz.isEmpty()) return -1;
    String[] czesci = odpowiedz.get(0).split(" ");
    if (czesci.length < 2) return -1;
    try { return Integer.parseInt(czesci[1]); } catch (NumberFormatException e) { return -1; }
}
System.out.println(extractStatusCode(rawHttpGet("example.com", "/")));

static Map<String,String> extractHeaders(List<String> odpowiedz) {
    Map<String,String> naglowki = new LinkedHashMap<>();
    for (int i=1;i<odpowiedz.size();i++) {
        String linia = odpowiedz.get(i);
        if (linia.isEmpty()) break;
        int idx = linia.indexOf(':');
        if (idx > 0) naglowki.put(linia.substring(0,idx).trim(), linia.substring(idx+1).trim());
    }
    return naglowki;
}
System.out.println(extractHeaders(rawHttpGet("example.com", "/")));

static String extractBody(List<String> odpowiedz) {
    int pustaLiniaIdx = odpowiedz.indexOf("");
    if (pustaLiniaIdx == -1 || pustaLiniaIdx == odpowiedz.size()-1) return "";
    return String.join("\n", odpowiedz.subList(pustaLiniaIdx+1, odpowiedz.size()));
}
System.out.println(extractBody(rawHttpGet("example.com", "/")).length());

