static List<String> rawHttpRequest(String host, String method, String path) {
    List<String> wynik = new ArrayList<>();
    try (Socket socket = new Socket(host, 80)) {
        socket.setSoTimeout(5000);
        String request = method+" "+path+" HTTP/1.1\r\nHost: "+host+"\r\nConnection: close\r\n\r\n";
        socket.getOutputStream().write(request.getBytes(StandardCharsets.UTF_8));
        BufferedReader reader = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        String linia; while ((linia = reader.readLine()) != null) wynik.add(linia);
    } catch (IOException e) {}
    return wynik;
}
System.out.println(rawHttpRequest("example.com", "HEAD", "/"));

static String extractHeaderValue(List<String> odpowiedz, String headerName) {
    return extractHeaders(odpowiedz).get(headerName);
}
System.out.println(extractHeaderValue(rawHttpGet("example.com", "/"), "Content-Type"));

long t0 = System.nanoTime();
List<String> odpowiedz = rawHttpGet("example.com", "/");
System.out.println((System.nanoTime()-t0)/1_000_000+"ms, linii: "+odpowiedz.size());

static boolean isRedirect(int statusCode) {
    return statusCode >= 300 && statusCode < 400;
}
List<String> odpowiedz = rawHttpGet("example.com", "/nieistniejaca-sciezka-xyz");
int kod = extractStatusCode(odpowiedz);
System.out.println("kod: "+kod+" przekierowanie: "+isRedirect(kod));

List<String> odpGet = rawHttpRequest("example.com", "GET", "/");
List<String> odpHead = rawHttpRequest("example.com", "HEAD", "/");
System.out.println("GET body dlugosc: "+extractBody(odpGet).length());
System.out.println("HEAD body dlugosc: "+extractBody(odpHead).length());

static boolean isClientError(int statusCode) { return statusCode >= 400 && statusCode < 500; }
static boolean isServerError(int statusCode) { return statusCode >= 500 && statusCode < 600; }
int kod = extractStatusCode(rawHttpGet("example.com", "/definitely-not-a-real-page-12345"));
System.out.println("kod: "+kod+" blad klienta: "+isClientError(kod));

static void debugRequest(String host, String path) {
    List<String> odpowiedz = rawHttpGet(host, path);
    System.out.println("status: "+extractStatusCode(odpowiedz));
    System.out.println("naglowki: "+extractHeaders(odpowiedz));
    System.out.println("dlugosc ciala: "+extractBody(odpowiedz).length());
}
debugRequest("example.com", "/");

