static String httpVersion(List<String> odpowiedz) {
    if (odpowiedz.isEmpty()) return "UNKNOWN";
    return odpowiedz.get(0).split(" ")[0];
}
System.out.println(httpVersion(rawHttpGet("example.com", "/")));

