static boolean hasHeader(List<String> odpowiedz, String headerName) {
    Map<String,String> naglowki = extractHeaders(odpowiedz);
    return naglowki.keySet().stream().anyMatch(k -> k.equalsIgnoreCase(headerName));
}
List<String> odp = rawHttpGet("example.com", "/");
System.out.println(hasHeader(odp, "content-type")+" "+hasHeader(odp, "Content-Type"));

static String buildRequestLine(String method, String path, String version) {
