static List<String> followRedirect(String host, String path, int maxHops) {
    String aktualnyHost = host, aktualnaSciezka = path;
    for (int hop=0;hop<maxHops;hop++) {
        List<String> odpowiedz = rawHttpGet(aktualnyHost, aktualnaSciezka);
        int kod = extractStatusCode(odpowiedz);
        if (!isRedirect(kod)) return odpowiedz;
        String location = extractHeaderValue(odpowiedz, "Location");
        if (location == null) return odpowiedz;
        System.out.println("przekierowanie do: "+location);
        // uproszczenie: zaklada wzgledna sciezke na TYM SAMYM hoscie
        aktualnaSciezka = location;
    }
    return List.of();
}
followRedirect("example.com", "/", 3);

