static int getContentLength(List<String> odpowiedz) {
    String wartosc = extractHeaderValue(odpowiedz, "Content-Length");
    try { return wartosc != null ? Integer.parseInt(wartosc) : -1; } catch (NumberFormatException e) { return -1; }
}
List<String> odpowiedz = rawHttpGet("example.com", "/");
int deklarowana = getContentLength(odpowiedz);
int faktyczna = extractBody(odpowiedz).length();
System.out.println("deklarowana: "+deklarowana+" faktyczna (znaki): "+faktyczna);

List<Boolean> wyniki = Collections.synchronizedList(new ArrayList<>());
ScheduledExecutorService monitor = Executors.newScheduledThreadPool(1);
ScheduledFuture<?> future = monitor.scheduleAtFixedRate(() -> wyniki.add(isSuccessStatus(extractStatusCode(rawHttpGet("example.com", "/")))), 0, 2000, TimeUnit.MILLISECONDS);
Thread.sleep(5000);
future.cancel(false);
monitor.shutdown(); monitor.awaitTermination(3, TimeUnit.SECONDS);
long sukcesy = wyniki.stream().filter(b -> b).count();
System.out.println("dostepnosc: "+sukcesy+"/"+wyniki.size());

class RawHttpClient {
    String describe(String host, String path) {
        List<String> odpowiedz = rawHttpGet(host, path);
        int kod = extractStatusCode(odpowiedz);
        String kategoria = isSuccessStatus(kod) ? "sukces" : isRedirect(kod) ? "przekierowanie" : isClientError(kod) ? "blad klienta" : isServerError(kod) ? "blad serwera" : "nieznany";
        return "status="+kod+" ("+kategoria+"), Content-Type="+extractHeaderValue(odpowiedz,"Content-Type")+", dlugosc ciala="+extractBody(odpowiedz).length();
    }
}
System.out.println(new RawHttpClient().describe("example.com", "/"));
